'use client';

import { useLayoutEffect, useEffect, useRef, useState } from 'react';
import { usePointerDrag } from './use-pointer-drag';
import { useReducedMotion } from './use-reduced-motion';
import './card-transfer-board.css';

export interface BoardCard {
  id: string;
  title: string;
  column: string;
}

export interface BoardColumn {
  id: string;
  title: string;
}

export interface CardTransferBoardProps {
  columns: BoardColumn[];
  cards: BoardCard[];
  onMove: (cardId: string, columnId: string) => void;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * Drag a card into another column, or use its "Move to" button. Cards in
 * both columns glide to close the gap and make room (measured positions
 * before and after the change, then animated between them).
 */
export function CardTransferBoard({
  columns,
  cards,
  onMove,
  className = '',
}: CardTransferBoardProps) {
  const board = useRef<HTMLDivElement>(null);
  const positions = useRef(new Map<string, DOMRect>());
  const [dragging, setDragging] = useState<{
    id: string;
    x: number;
    y: number;
    over: string | null;
  } | null>(null);
  const [message, setMessage] = useState('');
  const reduced = useReducedMotion();

  const snapshot = () => {
    const map = new Map<string, DOMRect>();
    board.current
      ?.querySelectorAll<HTMLElement>('[data-card]')
      .forEach((el) => map.set(el.dataset.card!, el.getBoundingClientRect()));
    return map;
  };

  useIsomorphicLayoutEffect(() => {
    const before = positions.current;
    const after = snapshot();
    if (!reduced)
      after.forEach((rect, id) => {
        const old = before.get(id);
        const el = board.current?.querySelector<HTMLElement>(
          `[data-card="${id}"]`
        );
        if (!old || !el?.animate) return;
        const dx = old.left - rect.left;
        const dy = old.top - rect.top;
        if (dx || dy)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: 'none' },
            ],
            {
              duration: 360,
              easing: 'cubic-bezier(0.2, 0.8, 0.2, 1)',
            }
          );
      });
    positions.current = after;
  }, [cards]);

  const transfer = (id: string, column: string) => {
    const card = cards.find((c) => c.id === id);
    if (!card || card.column === column) return;
    positions.current = snapshot();
    onMove(id, column);
    setMessage(
      `Moved “${card.title}” to ${columns.find((c) => c.id === column)?.title}.`
    );
  };

  const columnAt = (x: number, y: number) => {
    const el = document
      .elementFromPoint(x, y)
      ?.closest<HTMLElement>('[data-column]');
    return el && board.current?.contains(el) ? el.dataset.column! : null;
  };

  const dragId = useRef('');
  const drag = usePointerDrag({
    onStart: (event) => {
      if ((event.target as HTMLElement).closest('button')) return false;
      dragId.current = (event.currentTarget as HTMLElement).dataset.card!;
      setDragging({ id: dragId.current, x: 0, y: 0, over: null });
    },
    onMove: ({ dx, dy, clientX, clientY }) =>
      setDragging({
        id: dragId.current,
        x: dx,
        y: dy,
        over: columnAt(clientX, clientY),
      }),
    onEnd: ({ clientX, clientY }, cancelled) => {
      const over = cancelled ? null : columnAt(clientX, clientY);
      // Start the glide from where the card was dropped.
      positions.current = snapshot();
      setDragging(null);
      if (over) transfer(dragId.current, over);
    },
  });

  return (
    <div ref={board} className={`mg-board ${className}`}>
      {columns.map((column) => {
        const list = cards.filter((card) => card.column === column.id);
        return (
          <section
            key={column.id}
            className='mg-board__column'
            data-column={column.id}
            data-over={dragging?.over === column.id}
            aria-label={`${column.title}, ${list.length} ${list.length === 1 ? 'card' : 'cards'}`}
          >
            <h4>
              {column.title} <span>{list.length}</span>
            </h4>
            <ul>
              {list.map((card) => {
                const other = columns.find((c) => c.id !== column.id)!;
                const held = dragging?.id === card.id;
                return (
                  <li
                    key={card.id}
                    data-card={card.id}
                    data-held={held}
                    className='mg-board__card'
                    style={
                      held
                        ? {
                            transform: `translate(${dragging!.x}px, ${dragging!.y}px) rotate(2deg)`,
                          }
                        : undefined
                    }
                    {...drag}
                  >
                    <span>{card.title}</span>
                    <button
                      type='button'
                      aria-label={`Move ${card.title} to ${other.title}`}
                      onClick={() => transfer(card.id, other.id)}
                    >
                      {column.id === columns[0].id ? '→' : '←'}
                    </button>
                  </li>
                );
              })}
              {list.length === 0 ? (
                <li className='mg-board__empty'>Drop a card here</li>
              ) : null}
            </ul>
          </section>
        );
      })}
      <p className='mg-board__status' role='status'>
        {message}
      </p>
    </div>
  );
}

.mg-board {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  color: var(--mg-text, #ffffff);
}

.mg-board__column {
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 12px;
  background: var(--mg-raised, #1b1b1b);
  transition:
    border-color 160ms ease,
    background-color 160ms ease;
}

.mg-board__column[data-over='true'] {
  border-color: var(--mg-accent-text, #dce9f7);
  border-style: dashed;
  background: #1e2329;
}

.mg-board__column h4 {
  display: flex;
  justify-content: space-between;
  margin: 0 0 8px;
  font-size: 13px;
}

.mg-board__column h4 span {
  color: #b8b8b8;
  font-weight: 500;
}

.mg-board__column ul {
  display: grid;
  gap: 6px;
  min-height: 120px;
  margin: 0;
  padding: 0;
  list-style: none;
  align-content: start;
}

.mg-board__card {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 4px 4px 4px 10px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 8px;
  background: #121212;
  font-size: 13px;
  font-weight: 600;
  cursor: grab;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

.mg-board__card[data-held='true'] {
  z-index: 5;
  border-color: var(--mg-accent-text, #dce9f7);
  box-shadow: 0 16px 28px -14px rgba(0, 0, 0, 0.55);
  cursor: grabbing;
}

.mg-board__card button {
  flex: none;
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 6px;
  background: #1e2329;
  color: var(--mg-accent-text, #dce9f7);
  font: inherit;
  cursor: pointer;
}

.mg-board__card button:focus-visible {
  outline: 2px solid var(--mg-accent-text, #dce9f7);
}

.mg-board__empty {
  display: grid;
  place-items: center;
  min-height: 60px;
  border: 1px dashed #474747;
  border-radius: 8px;
  color: #8f8f8f;
  font-size: 12px;
}

.mg-board__status {
  grid-column: 1 / -1;
  min-height: 1.3em;
  margin: 0;
  color: #b8b8b8;
  font-size: 13px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-board__column {
    transition: none;
  }
}

'use client';

import { useRef, type PointerEvent as ReactPointerEvent } from 'react';

export interface DragState {
  /** Distance from where the drag started, in pixels. */
  dx: number;
  dy: number;
  /** Pointer position in viewport coordinates. */
  clientX: number;
  clientY: number;
  /** Smoothed velocity in pixels per millisecond. */
  vx: number;
  vy: number;
}

export interface PointerDragOptions {
  /** Return false to ignore this press. */
  onStart?: (event: ReactPointerEvent<HTMLElement>) => boolean | void;
  onMove?: (drag: DragState) => void;
  /**
   * `cancelled` is true when the browser took the gesture over, for example
   * to scroll the page on touch.
   */
  onEnd?: (drag: DragState, cancelled: boolean) => void;
}

interface Active {
  id: number;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  lastTime: number;
  vx: number;
  vy: number;
}

/**
 * Pointer-capture dragging for mouse, pen and touch. Spread the returned
 * handlers on the element that starts the drag. Pair it with a CSS
 * `touch-action` that leaves the scroll axis you still want to the browser.
 */
export function usePointerDrag(options: PointerDragOptions) {
  const latest = useRef(options);
  latest.current = options;
  const active = useRef<Active | null>(null);

  const snapshot = (a: Active, x: number, y: number): DragState => ({
    dx: x - a.startX,
    dy: y - a.startY,
    clientX: x,
    clientY: y,
    vx: a.vx,
    vy: a.vy,
  });

  const finish = (
    event: ReactPointerEvent<HTMLElement>,
    cancelled: boolean
  ) => {
    const a = active.current;
    if (!a || a.id !== event.pointerId) return;
    active.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
    // A pause before release means the pointer was not really flung.
    if (event.timeStamp - a.lastTime > 150) {
      a.vx = 0;
      a.vy = 0;
    }
    latest.current.onEnd?.(
      snapshot(a, event.clientX, event.clientY),
      cancelled
    );
  };

  return {
    onPointerDown(event: ReactPointerEvent<HTMLElement>) {
      if (event.button !== 0 || active.current) return;
      if (latest.current.onStart?.(event) === false) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      active.current = {
        id: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        lastTime: event.timeStamp,
        vx: 0,
        vy: 0,
      };
    },
    onPointerMove(event: ReactPointerEvent<HTMLElement>) {
      const a = active.current;
      if (!a || a.id !== event.pointerId) return;
      const dt = Math.max(1, event.timeStamp - a.lastTime);
      a.vx = a.vx * 0.6 + ((event.clientX - a.lastX) / dt) * 0.4;
      a.vy = a.vy * 0.6 + ((event.clientY - a.lastY) / dt) * 0.4;
      a.lastX = event.clientX;
      a.lastY = event.clientY;
      a.lastTime = event.timeStamp;
      latest.current.onMove?.(snapshot(a, event.clientX, event.clientY));
    },
    onPointerUp(event: ReactPointerEvent<HTMLElement>) {
      finish(event, false);
    },
    onPointerCancel(event: ReactPointerEvent<HTMLElement>) {
      finish(event, true);
    },
  };
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
